def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    try:
        if not isinstance(nanoseconds, int):
            raise ValueError("Invalid nanoseconds value, must be an integer.")

        seconds, nanos = divmod(nanoseconds, 1_000_000_000)
        microseconds, nanos = divmod(nanos, 1_000)

        if tz is None:
            import datetime
            return datetime.time(hour=0, minute=0, second=seconds, microsecond=microseconds)
        else:
            import datetime
            import pytz
            if isinstance(tz, str):
                tz = pytz.timezone(tz)
            elif not isinstance(tz, datetime.tzinfo):
                raise ValueError("Invalid timezone value, must be a string or datetime.tzinfo.")
            naive_time = datetime.time(hour=0, minute=0, second=seconds, microsecond=microseconds)
            naive_datetime = datetime.datetime.combine(datetime.date.today(), naive_time)
            return naive_datetime.astimezone(tz).time()
    except Exception as e:
        raise ValueError(f"Error hydrating time: {str(e)}")

def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    from datetime import timedelta, time, timezone

    try:
        # Convert nanoseconds to seconds and fractional seconds
        seconds = nanoseconds // 1_000_000_000
        nanos = nanoseconds % 1_000_000_000
        microseconds = nanos // 1_000

        # Create a time object from the seconds and microseconds
        if tz is None:
            # If no timezone is provided, assume UTC
            dt = time(hour=0, minute=0, second=0, microsecond=0, tzinfo=timezone.utc) + timedelta(seconds=seconds, microseconds=microseconds)
            return dt.time()
        else:
            # If a timezone is provided, use it
            dt = time(hour=0, minute=0, second=0, microsecond=0, tzinfo=tz) + timedelta(seconds=seconds, microseconds=microseconds)
            return dt.time()
    except Exception as e:
        raise ValueError(f"Invalid input: {e}")

