def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    from datetime import datetime, timedelta, timezone

    if not isinstance(nanoseconds, int):
        raise ValueError("nanoseconds must be an integer")

    # Assuming nanoseconds since the start of the day
    seconds, nanoseconds = divmod(nanoseconds, 1_000_000_000)
    minutes, seconds = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)

    # Create a datetime object for January 1, 1970, to use as a base for time
    base_time = datetime(1970, 1, 1, hour=hours, minute=minutes, second=seconds, microsecond=nanoseconds // 1000)

    if tz is not None:
        if not isinstance(tz, (int, float, timezone)):
            raise ValueError("tz must be an integer, float, or datetime.timezone object")
        if isinstance(tz, (int, float)):
            tz = timezone(timedelta(seconds=tz * 3600))
        return base_time.replace(tzinfo=tz)
    else:
        return base_time.time()

