def _get_resource_name_regex():
    """Build or return the regular expressions that are used to validate
    the name of the Krake resources.

    Returns:
        (re.Pattern): the compiled regular expressions, to validate
        the resource name.
    """
    try:
        import re
    except ImportError:
        raise ImportError("The re module is required to use this function.")

    # Define the regex pattern for a valid Krake resource name
    # A valid resource name should start with a lowercase letter or digit,
    # can be followed by any number of lowercase letters, digits, hyphens, or underscores,
    # and must end with a lowercase letter or digit.
    pattern = r'^[a-z0-9]([a-z0-9-_]*[a-z0-9])?$'

    try:
        return re.compile(pattern, re.IGNORECASE)
    except re.error as e:
        raise ValueError(f"Invalid regex pattern: {pattern}") from e

