def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
        :class:`list`).
    """
    if not isinstance(sql, (str, bytes)):
        raise ValueError("sql must be of type str or bytes")

    in_style = getattr(self, 'in_style', None)
    out_style = getattr(self, 'out_style', None)

    if in_style == out_style:
        return sql, params

    if in_style is None or out_style is None:
        raise ValueError("in_style and out_style must be set on the instance")

    if in_style == 'named' and not isinstance(params, collections.abc.Mapping):
        raise ValueError("params must be a Mapping when in_style is named")

    if in_style == 'ordinal' and not isinstance(params, collections.abc.Sequence):
        raise ValueError("params must be a Sequence when in_style is ordinal")

    if out_style == 'named':
        if in_style == 'ordinal':
            new_params = {f":{idx}": value for idx, value in enumerate(params, start=1)}
        else:
            new_params = {f":{key}": value for key, value in params.items()}
        formatted_sql = re.sub(r'(:\d+)', lambda m: f":{int(m.group(1))}", sql)
    elif out_style == 'ordinal':
        if in_style == 'named':
            new_params = [params[f":{idx}"] for idx in range(1, len(params) + 1)]
        else:
            new_params = list(params)
        formatted_sql = re.sub(r':\d+', lambda m: f"${int(m.group(0)[1:])}", sql)
    else:
        raise ValueError(f"Unsupported out_style: {out_style}")

    return formatted_sql, new_params

def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
		:class:`list`).
    """
    if not isinstance(sql, (str, bytes)):
        raise ValueError("SQL must be of type str or bytes")

    if not isinstance(params, (dict, list, tuple)):
        raise ValueError("Params must be of type dict, list, or tuple")

    in_style = self.SQLParams.in_style
    out_style = self.SQLParams.out_style

    if in_style == out_style:
        return sql, params

    if in_style == 'named':
        if not isinstance(params, dict):
            raise ValueError("Params must be a dict for named in-style parameters")
        param_dict = {}
        formatted_sql_parts = []
        current_param = []
        in_param_name = None

        def add_part():
            nonlocal current_param
            if current_param:
                formatted_sql_parts.append(''.join(current_param))
                current_param.clear()

        for char in sql:
            if char == ':':
                if in_param_name:
                    add_part()
                    if in_param_name in params:
                        param_dict[in_param_name] = params[in_param_name]
                    if out_style == 'pyformat':
                        current_param.append(f'%({in_param_name})s')
                    elif out_style == 'format':
                        current_param.append('%s')
                    elif out_style == 'qmark':
                        current_param.append('?')
                    in_param_name = None
                else:
                    current_param.append(':')
            elif in_param_name is not None:
                if char.isalnum() or char == '_':
                    in_param_name += char
                else:
                    add_part()
                    current_param.append(char)
                    in_param_name = None
            else:
                current_param.append(char)

        add_part()
        return ''.join(formatted_sql_parts), param_dict

    elif in_style == 'ordinal':
        if not isinstance(params, (list, tuple)):
            raise ValueError("Params must be a list or tuple for ordinal in-style parameters")
        param_list = []
        param_index = 0
        formatted_sql_parts = []
        current_param = []
        in_param_count = 0

        def add_part():
            nonlocal current_param
            if current_param:
                formatted_sql_parts.append(''.join(current_param))
                current_param.clear()

        for char in sql:
            if char == '%':
                if len(current_param) > 1 and current_param[-1] == 's':
                    current_param.pop()  # Remove 's' following '%'
                    add_part()
                    param_index += 1
                    if out_style == 'pyformat':
                        current_param.append(f'%({in_param_count})s')
                    elif out_style == 'named':
                        named_param = f'p{in_param_count}'
                        current_param.append(f':{named_param}')
                        param_dict[named_param] = params[in_param_count - 1]
                    elif out_style == 'qmark':
                        current_param.append('?')
                    in_param_count += 1
                else:
                    current_param.append('%')
            else:
                current_param.append(char)

        add_part()
        if out_style == 'pyformat':
            return ''.join(formatted_sql_parts), params
        elif out_style == 'named':
            return ''.join(formatted_sql_parts), param_dict
        elif out_style == 'qmark':
            return ''.join(formatted_sql_parts), params

    raise ValueError("Unsupported parameter style conversion")

