def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -	*params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
        *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	A :class:`list` containing each set of converted out-style
        parameters (:class:`dict` or :class:`list`).
    """
    import re
    from typing import Any, AnyStr, Dict, Iterable, List, Sequence, Tuple, Union

    # Helper function to convert placeholders
    def convert_placeholder(sql, param_style, out_style):
        if param_style == 'named':
            placeholder_pattern = re.compile(r':(\w+)')
        elif param_style in ('qmark', 'numeric', 'format', 'pyformat'):
            if param_style == 'qmark':
                placeholder_pattern = re.compile(r'\?')
            elif param_style == 'numeric':
                placeholder_pattern = re.compile(r':(\d+)')
            elif param_style == 'format':
                placeholder_pattern = re.compile(r'%s')
            elif param_style == 'pyformat':
                placeholder_pattern = re.compile(r'%\((\w+)\)s')
            else:
                raise ValueError(f"Unsupported param style: {param_style}")

            if out_style == 'qmark':
                return sql, '?'
            elif out_style == 'numeric':
                return sql, lambda i: f':{i}'
            elif out_style == 'format':
                return sql, '%s'
            elif out_style == 'pyformat':
                return sql, lambda i: f'%({i})s'
            else:
                raise ValueError(f"Unsupported out style: {out_style}")
        else:
            raise ValueError(f"Unsupported param style: {param_style}")

    # Determine the out-style parameter placeholder
    out_placeholder_generator = convert_placeholder(sql, self.in_style, self.out_style)[1]

    # Convert SQL and parameters
    converted_sql = sql
    converted_params = []

    if self.in_style == 'named':
        # Named style
        if self.out_style == 'named':
            # No conversion needed
            converted_sql = sql
            converted_params = many_params
        else:
            # Convert named to other styles
            new_sql_parts = []
            placeholders_iter = re.finditer(r':(\w+)', sql)
            last_end = 0
            param_index = 0
            for match in placeholders_iter:
                new_sql_parts.append(sql[last_end:match.start()])
                if self.out_style == 'qmark':
                    new_sql_parts.append('?')
                elif self.out_style == 'numeric':
                    new_sql_parts.append(f':{param_index+1}')
                elif self.out_style == 'format':
                    new_sql_parts.append('%s')
                elif self.out_style == 'pyformat':
                    new_sql_parts.append(f'%({match.group(1)})s')
                last_end = match.end()
                param_index += 1
            new_sql_parts.append(sql[last_end:])
            converted_sql = ''.join(new_sql_parts)

            for params in many_params:
                if isinstance(params, dict):
                    converted_params.append([params[key] for key in re.findall(r':(\w+)', sql)])
                else:
                    raise ValueError("For named parameter style, each params must be a dict")
    else:
        # Ordinal style
        if self.in_style == 'qmark':
            param_count = sql.count('?')
        elif self.in_style == 'numeric':
            param_count = len(re.findall(r':\d+', sql))
        elif self.in_style == 'format':
            param_count = sql.count('%s')
        elif self.in_style == 'pyformat':
            param_count = len(re.findall(r'%\(\w+\)s', sql))
        else:
            raise ValueError(f"Unsupported param style: {self.in_style}")

        if isinstance(out_placeholder_generator, str):
            converted_sql = sql.replace(convert_placeholder(sql, self.in_style, self.out_style)[0], out_placeholder_generator)
        else:
            new_sql_parts = []
            placeholders_iter = re.finditer(r'\?|:\d+|%s|%\(.*?\)s', sql)
            last_end = 0
            param_index = 0
            for match in placeholders_iter:
                new_sql_parts.append(sql[last_end:match.start()])
                new_sql_parts.append(out_placeholder_generator(param_index))
                last_end = match.end()
                param_index += 1
            new_sql_parts.append(sql[last_end:])
            converted_sql = ''.join(new_sql_parts)

        for params in many_params:
            if isinstance(params, Sequence) and len(params) == param_count:
                converted_params.append(params)
            else:
                raise ValueError(f"Each params must be a sequence of length {param_count}")

    return converted_sql, converted_params

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -   *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
