        *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -   The formatted SQL query (:class:`str` or :class:`bytes`).

    -   A :class:`list` containing each set of converted out-style
        parameters (:class:`dict` or :class:`list`).
    """
    from collections.abc import Mapping, Sequence
    import re

    if not isinstance(sql, (str, bytes)):
        raise ValueError("sql must be of type str or bytes")

    if not isinstance(many_params, Iterable):
        raise ValueError("many_params must be an iterable")

    out_style = self.SQLParams.out_style
    in_style = self.SQLParams.in_style

    if out_style == in_style:
        return sql, list(many_params)

    def convert_params(params):
        if in_style in {'named', 'pyformat'}:
            if not isinstance(params, Mapping):
                raise ValueError("params must be a mapping for named or pyformat style")
            if out_style == 'qmark':
                out_params = []
                out_sql = re.sub(r':(\w+)', lambda m: f'?{out_params.append(params[m.group(1)]) or ""}', sql)
                return out_sql, out_params
            elif out_style == 'numeric':
                out_params = []
                out_sql = re.sub(r':(\w+)', lambda m: f':{len(out_params)}{out_params.append(params[m.group(1)]) or ""}', sql)
                return out_sql, out_params
            elif out_style == 'format':
                out_params = [params[k] for k in sorted(params.keys(), key=lambda k: sql.find(f':{k}'))]
                return sql, out_params
        elif in_style in {'qmark', 'numeric', 'format'}:
            if not isinstance(params, Sequence):
                raise ValueError("params must be a sequence for qmark, numeric, or format style")
            if out_style == 'named':
                param_names = [f'p{i}' for i in range(len(params))]
                out_params = dict(zip(param_names, params))
                for i, name in enumerate(param_names):
                    sql = sql.replace(f':{name}', f':{name}')
                return sql, out_params
            elif out_style == 'pyformat':
                param_names = [f'p{i}' for i in range(len(params))]
