def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None or version is None:
        raise ValueError("Both inventory and version must be provided.")

    try:
        version_data = inventory.get_version_data(version)
    except KeyError:
        raise ValueError(f"Version {version} not found in inventory.")

    logical_path_map = {}

    for entry in version_data.get('entries', []):
        logical_path = entry.get('logical_path')
        content_file = entry.get('content_file')

        if logical_path and content_file:
            if logical_path not in logical_path_map:
                logical_path_map[logical_path] = set()
            logical_path_map[logical_path].add(content_file)

    return logical_path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not inventory or not isinstance(inventory, dict):
        raise ValueError("Inventory must be a non-empty dictionary.")

    if not isinstance(version, str) or not version:
        raise ValueError("Version must be a non-empty string.")

    if version not in inventory:
        raise KeyError(f"Version {version} not found in inventory.")

    logical_path_map = {}

    for item in inventory.get(version, []):
        logical_path = item.get('logical_path')
        content_file = item.get('content_file')

        if logical_path and content_file:
            if logical_path not in logical_path_map:
                logical_path_map[logical_path] = set()
