def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    import xml.etree.ElementTree as ET

    if not folder or not os.path.isdir(folder):
        raise ValueError("Invalid folder path provided")

    package_data = {}
    for root, _, files in os.walk(folder):
        for file in files:
            if file.endswith('.xml'):
                file_path = os.path.join(root, file)
                try:
                    tree = ET.parse(file_path)
                    root_element = tree.getroot()
                    base_name = os.path.splitext(file)[0]
                    if base_name not in package_data:
                        package_data[base_name] = []
                    package_data[base_name].append({
                        'file': file_path,
                        'xml_root': root_element
                    })
                except ET.ParseError:
                    print(f"Failed to parse XML file: {file_path}")
                except Exception as e:
                    print(f"An error occurred while processing {file_path}: {str(e)}")

    return package_data

