def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    import os

    if not isinstance(zip_path, str) or not zip_path:
        raise ValueError("zip_path must be a non-empty string")

    try:
        with zipfile.ZipFile(zip_path, 'r') as zin:
            xml_data = {}
            for zinfo in zin.infolist():
                if zinfo.filename.endswith('.xml'):
                    base_name = os.path.basename(zinfo.filename[:-4])  # Remove .xml extension
                    with zin.open(zinfo) as file:
                        content = file.read()
                        if base_name in xml_data:
                            xml_data[base_name].append(content)
                        else:
                            xml_data[base_name] = [content]
            return xml_data
    except zipfile.BadZipFile:
        raise ValueError("The file is not a valid zip archive")
    except Exception as e:
        raise Exception(f"An error occurred while exploring the zipfile: {str(e)}")

