def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = ' ' * indent
    parts = []

    try:
        if debug:
            parts.append(f"{indent_str}<Debug Info: {self.__class__.__name__}>")

        for key, value in self.__dict__.items():
            if isinstance(value, list):
                parts.append(f"{indent_str}{key}: [")
                for item in value:
                    if hasattr(item, 'pretty'):
                        parts.append(item.pretty(indent + 4, debug))
                    else:
                        parts.append(f"{' ' * (indent + 4)}{item}")
                parts.append(f"{indent_str}]")
            elif hasattr(value, 'pretty'):
                parts.append(f"{indent_str}{key}:")
                parts.append(value.pretty(indent + 4, debug))
            else:
                parts.append(f"{indent_str}{key}: {value}")
    except Exception as e:
        parts.append(f"{indent_str}Error pretty printing: {e}")

    return '\n'.join(parts)

