def normalized(self):
    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    >>> relativedelta(days=1.5, hours=2).normalized()
    relativedelta(days=+1, hours=+14)

    :return:
        Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """
    from dateutil.relativedelta import relativedelta
    # Extract all possible attributes from the relativedelta object
    attrs = ['years', 'months', 'days', 'leapdays', 'weeks', 'hours', 'minutes', 'seconds', 'microseconds']
    normalized_values = {}

    for attr in attrs:
        value = getattr(self, attr, 0)
        if isinstance(value, float):
            # Convert float values to integer and distribute the remainder
            int_value = int(value)
            normalized_values[attr] = int_value
            remainder = value - int_value
            if remainder > 0:
                # Distribute the remainder to the next smaller unit
                if attr == 'days':
                    normalized_values['hours'] = int(remainder * 24)
                elif attr == 'hours':
                    normalized_values['minutes'] = int(remainder * 60)
                elif attr == 'minutes':
                    normalized_values['seconds'] = int(remainder * 60)
                elif attr == 'seconds':
                    normalized_values['microseconds'] = int(remainder * 1e6)
        else:
            normalized_values[attr] = value

    return relativedelta(**normalized_values)

