def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import os
    import shutil

    try:
        if os.path.exists(self.storage_root):
            if not os.path.isdir(self.storage_root):
                raise FileExistsError(f"The path {self.storage_root} exists but is not a directory.")
            if os.listdir(self.storage_root):
                raise ValueError(f"The directory {self.storage_root} is not empty.")
        else:
            os.makedirs(self.storage_root, exist_ok=True)

        # Create the required OCFL directories
        required_dirs = [
            os.path.join(self.storage_root, '0=ocfl_1.0'),
            os.path.join(self.storage_root, 'inventory')
        ]
        for directory in required_dirs:
            os.makedirs(directory, exist_ok=True)

        # Create the OCFL root inventory file
        root_inventory_path = os.path.join(self.storage_root, '0=ocfl_1.0', 'inventory.json')
        with open(root_inventory_path, 'w') as f:
            f.write('{"id": "", "type": "ocfl_1.0", "digestAlgorithm": "sha512"}')

        # Optionally, create a README or other files as per OCFL spec
        readme_path = os.path.join(self.storage_root, 'README')
        with open(readme_path, 'w') as f:
            f.write("This directory is an OCFL storage root.")

    except Exception as e:
        # Clean up in case of error
        if os.path.exists(self.storage_root):
            shutil.rmtree(self.storage_root)
        raise RuntimeError(f"Failed to initialize OCFL storage root: {str(e)}")

