        raise ValueError(f"Failed to read root inventory from {version_dirs[0]}/inventory: {e}")

    for version_dir in version_dirs:
        try:
            with open(f'{version_dir}/inventory', 'r') as f:
                current_inventory = json.load(f)
        except (FileNotFoundError, json.JSONDecodeError) as e:
            raise ValueError(f"Failed to read inventory from {version_dir}/inventory: {e}")

