def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    import argparse
    import borgmatic.commands

    def generate_completion_script(parser, command_name=''):
        script = []
        if command_name:
            script.append(f'_borgmatic_{command_name}() {{')
        else:
            script.append('_borgmatic() {')
        script.append('    local cur')
        script.append('    COMPREPLY=()')
        script.append('    cur="${COMP_WORDS[COMP_CWORD]}"')
        script.append('    case "${COMP_CWORD}" in')

        actions = parser._actions
        subparsers = [action for action in actions if isinstance(action, argparse._SubParsersAction)]

        if subparsers:
            commands = list(subparsers[0].choices.keys())
            script.append(f'        1) COMPREPLY=( $(compgen -W "{ " ".join(commands)}" -- $cur) ) ;;')
            script.append('        *)')
        else:
            script.append('        *)')

        options = []
        for action in actions:
            if action.option_strings:
                options.extend(action.option_strings)
        script.append(f'            COMPREPLY=( $(compgen -W "{ " ".join(options)}" -- $cur) ) ;;')
        script.append('    esac')
        script.append('}')

        for action in subparsers:
            for command, parser in action.choices.items():
                script.extend(generate_completion_script(parser, command))

        script.append('complete -F _borgmatic borgmatic')
        if command_name:
            script.append(f'complete -F _borgmatic_{command_name} borgmatic {command_name}')

        return script

    try:
        main_parser = borgmatic.commands.parsers.parse_arguments()
        return '\n'.join(generate_completion_script(main_parser))
    except Exception as e:
        return f"# Failed to generate bash completion script: {str(e)}"

