    def format_choices(choices):
        if isinstance(choices, argparse.FileType):
            return ""
        return " " + " ".join(str(choice) for choice in choices) if choices else ""

    def generate_completion_script(parser, cmd_name='borgmatic'):
        script = [f"_borgmatic_{cmd_name}() {{"]
        script.append(f"    local cur prev opts")
        script.append("    COMPREPLY=()")
        script.append("    cur=\"${COMP_WORDS[COMP_CWORD]}\"")
        script.append("    prev=\"${COMP_WORDS[COMP_CWORD-1]}\"")
        script.append("    opts=\"\"")

        for action in parser._actions:
            if action.choices:
                opts += f" {format_choices(action.choices)}"
            elif action.option_strings:
                for option_string in action.option_strings:
                    opts += f" {option_string}"
                    if not action.nargs == 0:
                        opts += f"={action.metavar or action.dest.upper()}"

        script.append(f"    opts=\"{opts}\"")
        script.append("    COMPREPLY=( $(compgen -W \"${opts}\" -- ${cur}) )")
        script.append("    return 0")
        script.append("}")
        script.append(f"complete -F _borgmatic_{cmd_name} {cmd_name}")
        script.append("")

