def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not size:
        raise ValueError("Size cannot be an empty string")

    size = size.strip()
    suffix = size[-1].upper()
    factor = 1

    if suffix.isdigit():
        number = size
    else:
        number = size[:-1]
        if suffix == 'K':
            factor = 1000
        elif suffix == 'M':
            factor = 1000**2
        elif suffix == 'G':
            factor = 1000**3
        elif suffix == 'T':
            factor = 1000**4
        elif suffix == 'P':
            factor = 1000**5
        elif suffix == 'E':
            factor = 1000**6
        elif suffix == 'Z':
            factor = 1000**7
        elif suffix == 'Y':
            factor = 1000**8
        else:
            raise ValueError(f"Unknown suffix: {suffix}")

    try:
        number = float(number)
    except ValueError:
        raise ValueError(f"Invalid number: {number}")

    return int(number * factor)

