def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import shutil
    import subprocess
    from pathlib import Path, PosixPath
    from typing import Optional, Union

    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"The archive at {archive_path} does not exist.")

    if isinstance(tmp_path, PosixPath):
        tmp_path = str(tmp_path)

    # Create a temporary directory within the specified tmp_path
    temp_dir = os.path.join(tmp_path, os.path.basename(archive_path) + "_uncompressed")
    os.makedirs(temp_dir, exist_ok=True)

    try:
        # Uncompress the archive
        if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
            subprocess.run(['tar', '-xzf', archive_path, '-C', temp_dir], check=True)
        elif archive_path.endswith('.tar.bz2'):
            subprocess.run(['tar', '-xjf', archive_path, '-C', temp_dir], check=True)
        elif archive_path.endswith('.zip'):
            subprocess.run(['unzip', archive_path, '-d', temp_dir], check=True)
        else:
            raise ValueError(f"Unsupported archive format for {archive_path}")

        # Determine the file path within the archive
        if filename:
            file_path = os.path.join(temp_dir, filename)
            if not os.path.exists(file_path):
                raise FileNotFoundError(f"The file {filename} does not exist in the archive.")
        else:
            # If no filename is specified, use the archive's root directory
            file_path = temp_dir

        return f"file://{file_path}"

    except subprocess.CalledProcessError as e:
        shutil.rmtree(temp_dir, ignore_errors=True)
        raise RuntimeError(f"Failed to uncompress the archive: {e}")

    except Exception as e:
        shutil.rmtree(temp_dir, ignore_errors=True)
        raise e

    finally:
        # Clean up the temporary directory if no filename is specified
        if not filename:
            shutil.rmtree(temp_dir, ignore_errors=True)

