def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        output = subprocess.check_output(['git', 'check-ignore', '-v', '--'] + ignored, stderr=subprocess.STDOUT, text=True)
        ignored_files = set()
        for line in output.split('\n'):
            parts = line.split()
            if len(parts) > 1:
                ignored_files.add(parts[-1])
        sorted_ignored_files = sorted(ignored_files)
        return ','.join(sorted_ignored_files)
    except subprocess.CalledProcessError as e:
        # This exception will be raised if `git check-ignore` returns a non-zero exit code, which can happen if no files match
        return ''
    except Exception as e:
        # Catch any other exceptions just in case
        return ''

