    if not isinstance(x, (int, float, list, np.ndarray)):
        raise ValueError("Input x must be a number or an array of numbers.")
    x = np.array(x)
    return np.exp(-0.5 * ((x - mean) / sigma) ** 2) / (sigma * np.sqrt(2 * np.pi))

