def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import logging.config
    import os
    import toml
    from collections import defaultdict

    config_dict = {}
    log_records = []

    for config_filename in config_filenames:
        try:
            if not os.path.exists(config_filename):
                log_records.append(logging.LogRecord(
                    name="config_loader",
                    level=logging.ERROR,
                    pathname=__file__,
                    lineno=0,
                    msg=f"Configuration file {config_filename} does not exist.",
                    args=(),
                    exc_info=None
                ))
                continue

            with open(config_filename, 'r') as fd:
                raw_config = fd.read()

            try:
                config = toml.loads(raw_config)
            except toml.TomlDecodeError as e:
                log_records.append(logging.LogRecord(
                    name="config_loader",
                    level=logging.ERROR,
                    pathname=__file__,
                    lineno=0,
                    msg=f"Failed to parse configuration file {config_filename}: {str(e)}",
                    args=(),
                    exc_info=None
                ))
                continue

            if resolve_env:
                config = _resolve_env_variables(config)

            if overrides:
                _apply_overrides(config, overrides)

            config_dict[config_filename] = config

        except Exception as e:
            log_records.append(logging.LogRecord(
                name="config_loader",
                level=logging.ERROR,
                pathname=__file__,
                lineno=0,
                msg=f"An error occurred while processing configuration file {config_filename}: {str(e)}",
                args=(),
                exc_info=None
            ))

    return config_dict, log_records

def _resolve_env_variables(config):
    import os
    import re

    def resolve_value(value):
        if isinstance(value, str):
            matches = re.findall(r'\${([^}]+)}', value)
            for match in matches:
                env_value = os.getenv(match)
                if env_value is not None:
                    value = value.replace(f'${{{match}}}', env_value)
        return value

    def resolve_config(c):
        if isinstance(c, dict):
            return {k: resolve_config(resolve_value(v)) for k, v in c.items()}
        elif isinstance(c, list):
            return [resolve_config(resolve_value(item)) for item in c]
        else:
            return resolve_value(c)

    return resolve_config(config)

def _apply_overrides(config, overrides):
    for key, value in overrides.items():
        _set_value(config, key, value)

def _set_value(config, key, value):
    keys = key.split('.')
    for k in keys[:-1]:
        if k not in config:
            config[k] = {}
        config = config[k]
    config[keys[-1]] = value

