    errors = []

    if overrides is None:
        overrides = {}

    for filename in config_filenames:
        if not os.path.exists(filename):
            errors.append(logging.LogRecord(name='ConfigLoader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"Configuration file does not exist: {filename}", args=(), exc_info=None))
            continue

        try:
            with open(filename, 'r') as file:
                config = json.load(file)
        except (IOError, ValueError) as e:
            errors.append(logging.LogRecord(name='ConfigLoader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"Error reading or parsing configuration file: {filename}", args=(str(e),), exc_info=True))
            continue

        if resolve_env:
            config = {k: os.path.expandvars(v) if isinstance(v, str) else v for k, v in config.items()}

        config_dict[filename] = config

    # Apply overrides
    for key, value in overrides.items():
        for config in config_dict.values():
            config[key] = value

    return config_dict, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import logging
    import logging.config
    import toml
    import yaml
    import json

    if overrides is None:
        overrides = {}

    config_dict = {}
    log_records = []

    for config_filename in config_filenames:
        if not os.path.exists(config_filename):
            log_records.append(logging.LogRecord('config_loader', logging.ERROR, config_filename, 0, 
                                                 f"Config file does not exist: {config_filename}", (), None))
            continue

        try:
            with open(config_filename, 'r') as fd:
                raw_config = fd.read()

            if config_filename.endswith('.toml'):
                parsed_config = toml.loads(raw_config)
            elif config_filename.endswith('.yaml') or config_filename.endswith('.yml'):
                parsed_config = yaml.safe_load(raw_config)
            elif config_filename.endswith('.json'):
                parsed_config = json.loads(raw_config)
            else:
                log_records.append(logging.LogRecord('config_loader', logging.ERROR, config_filename, 0, 
                                                     f"Unsupported config file format: {config_filename}", (), None))
                continue

            if resolve_env:
                parsed_config = _resolve_env_vars(parsed_config)

            parsed_config.update(overrides)

            config_dict[config_filename] = parsed_config

        except Exception as e:
            log_records.append(logging.LogRecord('config_loader', logging.ERROR, config_filename, 0, 
                                                 f"Failed to parse config file {config_filename}: {str(e)}", (), None))

    return config_dict, log_records

def _resolve_env_vars(config):
    import os

    if isinstance(config, dict):
        return {k: _resolve_env_vars(v) for k, v in config.items()}
    elif isinstance(config, list):
        return [_resolve_env_vars(i) for i in config]
    elif isinstance(config, str) and config.startswith('$'):
        env_var_name = config[1:]
        return os.getenv(env_var_name, config)
    else:
        return config

