def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    metaclass = None
    for base in bases:
        try:
            if isinstance(base, type):
                base_metaclass = base.__class__
                if metaclass is None:
                    metaclass = base_metaclass
                elif metaclass is not base_metaclass:
                    raise TypeError("metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of the metaclasses of all its bases")
        except AttributeError:
            pass

    return metaclass if metaclass else type

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    metaclasses = set()
    for base in bases:
        try:
            metaclass = type(base)
            if metaclass not in metaclasses:
                metaclasses.add(metaclass)
        except Exception:
            continue

    if not metaclasses:
        return type

    if len(metaclasses) == 1:
        return metaclasses.pop()

