def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError("dictionary is empty")

    # Find the least frequently used item
    lfu_key = min(self._frequency, key=self._frequency.get)

    # Remove the item from the frequency dictionary
    del self._frequency[lfu_key]

    # Remove and return the item from the main dictionary
    return lfu_key, self.pop(lfu_key)

