    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError('dictionary is empty')
    h = self.hq[0]
    while h[1] != self[self._mapping[h[2]]][0]:
        heappop(self.hq)
        h = self.hq[0]
    heappop(self.hq)
    key = h[2]
