def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    import re
    tags = set()
    replaced_text = []
    in_code_block = False

    def is_code_block_line(line):
        return line.strip().startswith('```')

    tag_pattern = re.compile(r'(?<!\w)(#\w+)')

    for line in text.split('\n'):
        if is_code_block_line(line):
            in_code_block = not in_code_block

        if in_code_block:
            replaced_text.append(line)
            continue

        new_line = line
        if not in_code_block:
            for match in tag_pattern.finditer(line):
                tag = match.group(1)
                tags.add(tag)
                if replacer:
                    replacement = replacer(tag)
                    new_line = new_line.replace(tag, replacement, 1)

        replaced_text.append(new_line)

    return tags, '\n'.join(replaced_text)

