    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        from Crypto.PublicKey import RSA
        from Crypto.Signature import PKCS1_v1_5
        from Crypto.Hash import SHA256
        import base64
        from xml.etree import ElementTree as ET

        # Parse the XML document to ensure it's valid
        try:
            ET.fromstring(doc)
        except ET.ParseError:
            raise ValueError("Invalid XML document")

        # Decode the base64 encoded signature
        try:
            signature = base64.b64decode(signature)
        except Exception as e:
            raise ValueError("Invalid base64 encoded signature") from e

        # Load public key
        try:
            key = RSA.import_key(public_key)
        except (ValueError, IndexError) as e:
            raise ValueError("Invalid public key") from e

        # Create a SHA-256 hash of the document
        h = SHA256.new(doc.encode('utf-8'))

        # Verify the signature
        verifier = PKCS1_v1_5.new(key)
        if verifier.verify(h, signature):
            return True
        else:
            return False

    except Exception as e:
        raise RuntimeError("An error occurred during signature verification") from e

