def list_of_file_names(settings_dirs, spec_option):
    """Create a list of file names based on the given directories and specification option
    """
    import os

    file_names = []
    try:
        for directory in settings_dirs:
            if os.path.isdir(directory):
                for fname in os.listdir(directory):
                    if fname.endswith(spec_option):
                        file_names.append(os.path.join(directory, fname))
    except TypeError:
        print("Invalid input: settings_dirs should be a list of strings and spec_option should be a string.")
    except Exception as e:
        print(f"An error occurred: {e}")

    return file_names

