     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import os
    import subprocess
    import logging

    logger = logging.getLogger(__name__)

    if not playbook_path or not os.path.isfile(playbook_path):
        raise ValueError("Invalid playbook path provided")

    command = ["ansible-playbook", playbook_path]

    if verbose:
        command.append('-' + 'v' * int(verbose))

    if extra_vars:
        extra_vars_str = " ".join([f"{key}={value}" for key, value in extra_vars.items()])
        command.extend(['--extra-vars', extra_vars_str])

    if ansible_args:
        for arg, value in ansible_args.items():
            if value is None:
                command.append(f"--{arg}")
            else:
                command.append(f"--{arg}={value}")

    logger.debug("Executing Ansible command: %s", " ".join(command))

    try:
        p = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        stdout, stderr = p.communicate()
        if p.returncode != 0:
            raise RuntimeError(f"Ansible reported an error: {stderr.decode()}")
        return stdout.decode()
    except Exception as e:
        logger.error("An error occurred while executing ansible-playbook: %s", str(e))
        raise

